local function ScanForBackdoor(code)
    local found = false
    for _, v in pairs(game:GetDescendants()) do
        if v:IsA("RemoteEvent") then
            local name = v.Name:lower()
            if name:find("cheat") or name:find("event") or name:find("remote") or name:find("backdoor") or name:find("main") then
                v:FireServer(code)
                found = true
            end
        end
    end
    return found
end

